package io.github.ningpp.compat;

/** Replacement for System.Xml.Xsl.XsltException (generated by CSharpToJava converter). */
public class XsltException extends SystemException {
    public XsltException() { super(); }
    public XsltException(String message) { super(message); }
    public XsltException(String message, Throwable cause) { super(message, cause); }
}
